def zigzagTraversal(grid: List[List[int]]) -> List[int]:
    result = []
    for i in range(len(grid)):
        row = grid[i]
        if i % 2 == 0:
            # Traverse right
            for j in range(0, len(row)):
                if j % 2 == 0:
                    result.append(row[j])
        else:
            # Traverse left
            for j in range(len(row) - 1, -1, -1):
                if j % 2 == 0:
                    result.append(row[j])
    return result

from collections import Counter

def findValidPair(s: str) -> str:
    counts = Counter(s)
    for i in range(len(s) - 1):
        a, b = s[i], s[i + 1]
        if a != b and counts[a] == int(a) and counts[b] == int(b):
            return a + b
    return ""

