def minMaxWeight(n: int, edges: List[List[int]], threshold: int) -> int:
    # Helper function to check reachability using BFS
    def bfs_check(max_weight: int) -> bool:
        from collections import defaultdict, deque
        graph = defaultdict(list)

        # Build a graph with filtered edges
        for u, v, w in edges:
            if w <= max_weight:
                graph[u].append(v)

        # BFS to check if all nodes can reach node 0
        queue = deque([0])
        visited = set([0])

        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

        # Check for out-degrees after BFS
        if len(visited) != n:
            return False

        out_degree = [0] * n
        for u in graph:
            out_degree[u] = len(graph[u])

        # Check if out-degree exceeds threshold
        return all(deg <= threshold for deg in out_degree)

    # Binary search for the minimum maximum weight
    left, right = 1, 10**6
    answer = -1

    while left <= right:
        mid = (left + right) // 2
        if bfs_check(mid):
            answer = mid
            right = mid - 1
        else:
            left = mid + 1

    return answer

