def minCost(n: int, cost: List[List[int]]) -> int:
    # Dynamic programming table to store the minimum costs
    dp = [[0] * 3 for _ in range(n)]

    # Base case: initialize the first house costs
    for j in range(3):
        dp[0][j] = cost[0][j]

    # Fill out the DP table
    for i in range(1, n):
        for j in range(3):
            dp[i][j] = cost[i][j] + min(
                dp[i - 1][(j + 1) % 3],
                dp[i - 1][(j + 2) % 3]
            )

    # Find minimum cost with equidistant constraints
    min_cost = float('inf')
    for j in range(3):
        for k in range(3):
            if j != k:
                min_cost = min(min_cost, dp[n - 1][j] + cost[n - 2][k])

    return min_cost

